      "evidence_type": "market_research",
      "decision_hygiene": "Write down an expected price range before the vendor conversation."
    }
  },
  "scenario_contexts": {
    "edge_capacity_tco": {
      "trigger_description": "If Engineering Capacity proves less available than assumed, pressure on Total Cost of Ownership increases.",
